/** @param {NS} ns */
export async function main(ns) {
  const targets = [];

  // Recursive scan from home, collect all servers
  function scan(srv, visited = new Set()) {
    if (visited.has(srv)) return;
    visited.add(srv);
    targets.push(srv);
    const neighbors = ns.scan(srv);
    for (const neighbor of neighbors) {
      scan(neighbor, visited);
    }
  }

  scan('home');

  // Try to nuke every server
  for (const srv of targets) {
    try { ns.nuke(srv); } catch(e) {}
  }

  // Filter to rooted servers with money potential (exclude home)
  const rooted = targets.filter(srv => 
    srv !== 'home' && ns.hasRootAccess(srv) && ns.getServerMaxMoney(srv) > 0
  );

  if (rooted.length === 0) {
    ns.print('No hackable targets found');
    return;
  }

  // Pick best target (highest maxMoney)
  let target = rooted[0];
  for (const srv of rooted) {
    if (ns.getServerMaxMoney(srv) > ns.getServerMaxMoney(target)) {
      target = srv;
    }
  }

  ns.print(`Targeting: ${target}`);

  // Infinite hack loop
  while (true) {
    const sec = ns.getServerSecurityLevel(target);
    const minSec = ns.getServerMinSecurityLevel(target);
    const money = ns.getServerMoneyAvailable(target);
    const maxMoney = ns.getServerMaxMoney(target);

    if (sec > minSec + 3) {
      await ns.weaken(target);
    } else if (money < maxMoney * 0.8) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
  }
}

