export async function main(ns) {
  const servers = new Set();
  const queue = ['home'];
  while (queue.length > 0) {
    const curr = queue.shift();
    for (const next of ns.scan(curr)) {
      if (!servers.has(next)) {
        servers.add(next);
        queue.push(next);
      }
    }
  }

  for (const srv of servers) {
    if (!ns.hasRootAccess(srv)) {
      ns.nuke(srv);
    }
  }

  let target = null;
  if (servers.has('n00dles')) {
    target = 'n00dles';
  } else {
    const candidates = Array.from(servers)
      .filter(s => s !== 'home' && ns.hasRootAccess(s) && ns.getServerMaxMoney(s) > 0 && ns.getServerMinSecurityLevel(s) <= 10)
      .sort((a, b) => {
        const ratioA = ns.getServerMaxMoney(a) / ns.getServerMinSecurityLevel(a);
        const ratioB = ns.getServerMaxMoney(b) / ns.getServerMinSecurityLevel(b);
        return ratioB - ratioA;
      });
    if (candidates.length > 0) {
      target = candidates[0];
    } else {
      target = Array.from(servers)
        .filter(s => s !== 'home' && ns.hasRootAccess(s) && ns.getServerMaxMoney(s) > 0)
        .sort((a, b) => ns.getServerMinSecurityLevel(a) - ns.getServerMinSecurityLevel(b))[0];
    }
  }
  ns.print(`Target: ${target}`);

  const minSec = ns.getServerMinSecurityLevel(target);
  const maxMoney = ns.getServerMaxMoney(target);

  while (true) {
    const sec = ns.getServerSecurityLevel(target);
    const money = ns.getServerMoneyAvailable(target);

    if (sec > minSec + 2) {
      await ns.weaken(target);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
  }
}

/** @param {NS} ns */
export async function main(ns) {
  // BFS scan to discover all servers
  const queue = ['home'];
  const visited = new Set(['home']);
  const servers = [];

  while (queue.length > 0) {
    const current = queue.shift();
    const neighbors = ns.scan(current);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push(neighbor);
        servers.push(neighbor);
      }
    }
  }

  // Try to nuke each server
  for (const server of servers) {
    try {
      ns.nuke(server);
    } catch (e) {
      // ignore
    }
  }

  // Collect rooted servers
  const rooted = [];
  for (const server of servers) {
    if (ns.hasRootAccess(server)) {
      rooted.push(server);
    }
  }

  // Pick target
  let target = rooted.includes('n00dles') ? 'n00dles' : rooted[0];
  if (!target) target = 'n00dles';

  // Infinite cycle: weaken, grow, hack, hack, hack
  while (true) {
    await ns.weaken(target);
    await ns.grow(target);
    await ns.hack(target);
    await ns.hack(target);
    await ns.hack(target);
  }
}
